/// The curated default set (Lucide only; empty for other packs).
pub const default_icons = [_]IconName{};

/// True when the icon ships in the default curated set.
pub fn isDefault(name: IconName) bool {
    for (default_icons) |candidate| {
        if (candidate == name) return true;
    }
    return false;
}

test "icon table is consistent" {
    try std.testing.expectEqual(count, bytes_table.len);
}
